// Embeds spec/reserved.json into src/reserved-data.ts so the built library needs no file at runtime.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = join(here, "..", "..", "spec", "reserved.json");
const data = JSON.parse(readFileSync(source, "utf8"));
const names = data.names.map((entry) => entry.name);
const body =
  "// Generated by scripts/embed-reserved.mjs from spec/reserved.json. Do not edit.\n" +
  `export const RESERVED_NAMES: readonly string[] = ${JSON.stringify(names)};\n`;
writeFileSync(join(here, "..", "src", "reserved-data.ts"), body);
